CREATE TABLE tasks(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), session_id TEXT NOT NULL DEFAULT '', request_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('accepted','running','waiting_user','unknown','completed','failed','cancelled')), revision INTEGER NOT NULL DEFAULT 1, current_attempt INTEGER NOT NULL DEFAULT 0, frozen_input_json TEXT NOT NULL, provider_json TEXT NOT NULL, view_json TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(project_id,request_id));
CREATE TABLE task_attempts(task_id TEXT NOT NULL REFERENCES tasks(id), attempt INTEGER NOT NULL, state TEXT NOT NULL, upstream_id TEXT, submit_started_at INTEGER, accepted_at INTEGER, result_json TEXT, error_json TEXT, created_at INTEGER NOT NULL, PRIMARY KEY(task_id,attempt));
CREATE TABLE task_outputs(task_output_key TEXT PRIMARY KEY, task_id TEXT NOT NULL, attempt INTEGER NOT NULL, output_key TEXT NOT NULL, role TEXT NOT NULL, state TEXT NOT NULL, path TEXT, asset_id TEXT REFERENCES assets(id), version_id TEXT REFERENCES versions(id), source_json TEXT, UNIQUE(task_id,attempt,output_key), FOREIGN KEY(task_id,attempt) REFERENCES task_attempts(task_id,attempt));
CREATE TABLE generation_inputs(task_id TEXT NOT NULL REFERENCES tasks(id), ordinal INTEGER NOT NULL, asset_id TEXT NOT NULL REFERENCES assets(id), version_id TEXT REFERENCES versions(id), role TEXT NOT NULL, PRIMARY KEY(task_id,ordinal));
-- ponytail: retain all events for lossless replay; add an explicit retention/cursor migration when disk growth warrants it.
CREATE TABLE events(id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT REFERENCES projects(id), session_id TEXT NOT NULL DEFAULT '', task_id TEXT REFERENCES tasks(id), type TEXT NOT NULL, payload_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX events_project_cursor ON events(project_id,id);
